struct Nodo: Equatable {
    var tipo: String
    var texto: String
    var hijos: [Nodo] = []
}

func cuerpo(puntos: Int, jugando: Bool) -> Nodo {
    Nodo(tipo: "Columna", texto: "", hijos: [
        Nodo(tipo: "Texto", texto: "Puntos: \(puntos)"),
        Nodo(tipo: "Boton", texto: jugando ? "Pausar" : "Seguir"),
    ])
}

let v1 = cuerpo(puntos: 10, jugando: true)
let v2 = cuerpo(puntos: 15, jugando: true)   // cambió solo el estado «puntos»
// diferencias(v1, v2) recorre los dos árboles y compara nodo por nodo

@main
struct MiApp: App {
    var body: some Scene {
        WindowGroup {
            BotonJugar()
        }
    }
}

struct BotonJugar: View {
    @State private var jugando = false      // el estado

    var body: some View {                   // la descripción
        Button(jugando ? "Pausar" : "Seguir") {
            jugando.toggle()                // al cambiar, SwiftUI recalcula body
        }
    }
}

